-- Persist the existing curated catalog in Supabase without replacing its source files.
-- IDs remain stable; rerunning this seed never overwrites an existing row.
begin;

create table public.catalog_entries (
  id text primary key
    check (id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$'),
  entry jsonb not null
    check (jsonb_typeof(entry) = 'object')
    check (entry ->> 'id' = id)
    check (length(btrim(coalesce(entry ->> 'name_de', ''))) between 1 and 200)
    check (length(btrim(coalesce(entry ->> 'category', ''))) between 1 and 80),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);

comment on table public.catalog_entries is
  'Shared Once Human catalog entries; stable IDs and JSON preserve the existing catalog item fields.';

alter table public.catalog_entries enable row level security;
revoke all on table public.catalog_entries from public, anon, authenticated;
grant select on table public.catalog_entries to anon, authenticated;
grant insert on table public.catalog_entries to authenticated;
grant update (entry, revision, updated_at, updated_by) on table public.catalog_entries to authenticated;

create policy catalog_entries_public_read
on public.catalog_entries for select to anon, authenticated
using (true);

create policy catalog_entries_moderator_insert
on public.catalog_entries for insert to authenticated
with check (
  (select private.has_role_at_least('moderator'::public.app_role))
  and updated_by = (select auth.uid())
);

create policy catalog_entries_moderator_update
on public.catalog_entries for update to authenticated
using ((select private.has_role_at_least('moderator'::public.app_role)))
with check (
  (select private.has_role_at_least('moderator'::public.app_role))
  and updated_by = (select auth.uid())
);

-- Seed only the current 21 base entries. Existing rows are preserved on reruns.
insert into public.catalog_entries (id, entry)
